from zalib import *
tib,fib,tal,cal='Tibia','Fibula','Talus','Calcaneus'
F5=['first','second','third','fourth','fifth'];mt=[f.capitalize()+' metatarsal bone' for f in F5]
pp=['Proximal phalanx of %s finger of foot'%f for f in F5];mp=['Middle phalanx of %s finger of foot'%f for f in F5[1:]];dp=['Distal phalanx of %s finger of foot'%f for f in F5]
ml=ext(fib,'down');mm=ext(tib,'down');heel=ext(cal,'back');hp=ext(cal,'down',frac=.06)
H=[ext(m,'front',frac=.06) for m in mt];mtp1=near(mt[0],pp[0]);nav=ext('Navicular bone','med+0.4down');b5=ext(mt[4],'back+0.5lat');ank=near(tib,tal)
J=Joint('pied','Cheville et pied','Cheville et pied droits',mix(ank,H[1],.35),470,view='cote')
J.use()
J.bone('tibia','Tibia',tib,cap=5000);J.bone('fibula','Fibula',fib,cap=3000);J.bone('talus','Talus',tal,cap=3000);J.bone('calca','Calcanéus',cal,cap=3500)
J.bone('tarse','Os du tarse',['Navicular bone','Cuboid bone','Medial cuneiform bone','Intermediate cuneiform bone','Lateral cuneiform bone'],cap=1800)
J.bone('meta','Métatarsiens',mt,cap=2200);J.bone('phal','Phalanges',pp+mp+dp+['Sesamoid bones of foot'],cap=900)
J.real('apon','Aponévrose plantaire','lig','Plantar aponeurosis',color='#e9c46a',op=.9,cap=5000)
J.real('tach','Tendon d’Achille','ten','Calcaneal tendon',cap=3500)
J.real('ltfa','Ligament talo-fibulaire antérieur','lig','Anterior talofibular ligament')
J.real('lcf','Ligament calcanéo-fibulaire','lig','Calcaneofibular ligament')
J.real('ltfp','Ligament talo-fibulaire postérieur','lig','Posterior talofibular ligament')
J.real('synd','Ligaments tibio-fibulaires','lig',['Anterior tibiofibular ligament','Posterior tibiofibular ligament'])
J.real('ldelt','Ligament deltoïde','lig',['Posterior tibiotalar ligament','Tibiocalcaneal ligament','Tibionavicular ligament'])
J.real('spring','Ligament calcanéo-naviculaire plantaire','lig','Plantar calcaneonavicular ligament')
J.real('rtar','Rétinaculum des fléchisseurs','lig','Flexor retinaculum of ankle',op=.6)
J.real('rfib','Rétinaculums des fibulaires','lig',['Superior fibular retinaculum','Inferior fibular retinaculum'],op=.6)
J.real('g-tibp','Gaine du tibial postérieur','ten','Tendon sheath of tibialis posterior muscle',color='#f6efe0',op=.7)
J.real('g-fib','Gaine des fibulaires','ten','Common tendon sheath of fibularis muscles',color='#f6efe0',op=.7)
J.real('b-ach','Bourses du talon','cart',['Subtendinous calcaneal bursa','Subcutaneous calcaneal bursa'],op=.75)
J.real('cap-mtp','Capsules et plaques plantaires des orteils','lig',['Articular capsules of metatarsophalangeal joints','Plantar metatarsophalangeal ligaments'],color='#cfe3ee',op=.6,cap=3000)
J.real('ltm','Ligament transverse des métatarsiens','lig','Deep transverse metatarsal ligament')
J.mus('tri','Mollet : soléaire et jumeaux',['Soleus muscle','Medial head of gastrocnemius','Lateral head of gastrocnemius'],cap=4000)
J.mus('tibp','Tibial postérieur','Tibialis posterior muscle',tlabel='Tendon du tibial postérieur')
J.mus('tiba','Tibial antérieur','Tibialis anterior muscle')
J.mus('fib','Fibulaires',['Fibularis longus muscle','Fibularis brevis muscle'],tlabel='Tendons fibulaires')
J.mus('flech','Longs fléchisseurs des orteils',['Flexor hallucis longus','Flexor digitorum longus'])
J.mus('ext','Extenseurs des orteils',['Extensor hallucis longus','Extensor digitorum longus'])
J.mus('abdh','Abducteur de l’hallux','Abductor hallucis')
J.mus('addh','Adducteur de l’hallux',['Oblique head of adductor hallucis','Transverse head of adductor hallucis'])
J.mus('fdb','Court fléchisseur des orteils','Flexor digitorum brevis')
J.real('nt','Nerf tibial et nerfs plantaires','nerf',['Tibial nerve','Medial plantar nerve','Lateral plantar nerve'],cap=2500)
J.real('ndig','Nerfs digitaux plantaires','nerf',['Common plantar digital branches of medial plantar nerve','Common plantar digital branches of lateral plantar nerve','Proper plantar digital branches of medial plantar nerve','Proper plantar digital branches of lateral plantar nerve'],cap=2500)
J.ent('e-ach','Attache du tendon d’Achille','Triceps surae muscle.e')
J.ent('e-apon','Attache de l’aponévrose sur le talon','Flexor digitorum brevis.o')
mort=snap('Common plantar digital branches of lateral plantar nerve',mix(H[2],H[3])+vec('down')*4)
if np.linalg.norm(mort-mix(H[2],H[3]))>22: mort=mix(H[2],H[3])+vec('down')*4
J.blob('mort','Névrome de Morton, lorsqu’il existe','nerf',mort,(4.5,8,4.5))
bun=off(mtp1,'med',10)
J.blob('bun','Bourse de l’oignon','cart',bun,(5,10,8),op=.7)
J.skin([mix(ank,H[1],.4),ank+vec('up')*60],170,cap=12000)
ach=V('Calcaneal tendon');achm=ach[(ach[:,2]>heel[2]+25)&(ach[:,2]<heel[2]+60)].mean(0)
apo=cen('Flexor digitorum brevis.or') if has('Flexor digitorum brevis.or','') else hp+vec('front')*8
tp_m=snap('Tendon sheath of tibialis posterior muscle',mm+vec('back')*6+vec('down')*4);fb_m=snap('Common tendon sheath of fibularis muscles',ml+vec('back')*8)
nt_t=snap('Tibial nerve',mm+vec('back')*14+vec('down')*6);atf=cen('Anterior talofibular ligament');cf=cen('Calcaneofibular ligament')
for a in [('talon','w','Sous le talon ou derrière'),('dehors','w','Sur le côté extérieur de la cheville'),('dedans','w','Sur le côté intérieur de la cheville'),('avantpied','w','Sous l’avant du pied'),('gros','w','Au gros orteil'),('dessus','w','Sur le dessus du pied'),
 ('matin','q','Aux premiers pas du matin'),('torsion','q','Après une torsion'),('course','q','En courant ou en sautant'),('chaussure','q','Dans la chaussure, soulagé pieds nus'),('decharge','q','Brûlure ou décharge électrique'),('instable','q','La cheville se dérobe'),('raide','q','Raide, bosse sur une articulation'),('affaisse','q','La voûte du pied s’affaisse'),('gonfle','q','Ça gonfle'),('nuit','q','La nuit ou au repos')]: J.sym(*a)
p=J.p
p('hallux',['bun','c-meta','c-phal','m-abdh','cap-mtp'],[(bun,17)],[(off(mtp1,'med',10),28)],tags=['gros','chaussure','raide'],view='dedans')
p('talon',['e-apon','apon','calca'],[(apo,19)],[(hp+vec('front')*6,34)],tags=['talon','matin'],view='dessous')
p('entorse',['ltfa','lcf'],[(atf,15),(cf,13)],[(ml+vec('front')*12+vec('down')*6,40)],tags=['dehors','torsion','gonfle'])
p('achille',['tach','e-ach','b-ach'],[(achm,24)],[(achm+vec('back')*4,36)],tags=['talon','matin','course'],view='dos')
p('metat',['cap-mtp','meta','ltm'],[(H[1]+vec('down')*5,14),(H[2]+vec('down')*5,14)],[(mix(H[1],H[2])+vec('down')*6,30)],tags=['avantpied','chaussure','course'],view='dessous')
p('morton',['mort','ndig','ltm'],[(mort,13)],[(mort+vec('down')*3,24),(mort+vec('front')*30,20)],tags=['avantpied','decharge','chaussure'],view='dessous')
p('tibpost',['g-tibp','t-tibp','m-tibp','spring'],[(tp_m,17),(nav,15)],[(mix(mm,nav)+vec('med')*4,38)],tags=['dedans','affaisse','course'],view='dedans')
p('instab',['ltfa','lcf','m-fib','t-fib'],[(atf,18),(cf,15)],[(ml+vec('front')*8,42)],tags=['dehors','instable','torsion'])
p('fibulaires',['g-fib','t-fib','rfib','m-fib'],[(fb_m,16),(mix(ml,b5)+vec('down')*4,15)],[(ml+vec('back')*6,34)],tags=['dehors','course'])
p('rigidus',['c-meta','c-phal','cap-mtp'],[(mtp1+vec('up')*4,15)],[(mtp1+vec('up')*8,24)],tags=['gros','raide','dessus'],view='dessus')
p('fatigue',['meta'],[(cen(mt[1]),15),(cen(mt[2]),12)],[(cen(mt[1])+vec('up')*8,28)],tags=['dessus','course','gonfle'],view='dessus')
p('tarsien',['nt','rtar'],[(nt_t,18)],[(mm+vec('back')*10+vec('down')*8,28),(mix(hp,H[2],.5)+vec('down')*4,45)],tags=['dedans','decharge','nuit','avantpied'],view='dedans')
J.write()
